contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        require(v > cBefore);

        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted && address(c).balance == cBefore && address(this).balance == thisBefore);
    }

    receive() external payable {}
}

