// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        vm.assume(v > cBefore);
        bool reverted;
        try c.withdraw(v) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == cBefore && address(this).balance == thisBefore);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
